package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.util.UUID;
/** Bounded metadata only. No payloads, addresses, route names, identifiers or raw exceptions. */
public final class StabilityJournal {
 private static SharedPreferences prefs(Context c){return c.getSharedPreferences("loki_stability",0);}
 public static void note(Context c,String kind,String phase,String reason,long duration){note(c,UUID.randomUUID().toString(),kind,phase,reason,duration);}
 public static synchronized void note(Context c,String operationId,String kind,String phase,String reason,long duration){if(operationId==null||!operationId.matches("[a-f0-9-]{36}"))throw new IllegalArgumentException("opaque operation identifier required");if(kind==null||phase==null||reason==null||!kind.matches("APP|CONVERSATION|PHOTO|NAVIGATION|SYNC|IMAGE|VIDEO|MEETING|IMPORT")||!phase.matches("START|END|TIMEOUT|RESULT_UNKNOWN|RECOVERY_REQUIRED|BACKGROUND|FOREGROUND|CANCELLED|ERROR")||!reason.matches("NONE|DEADLINE|RESTART|CONNECTION|LIFECYCLE|STATE_CHANGED"))throw new IllegalArgumentException("fixed diagnostic vocabulary required");try{JSONArray rows=snapshot(c).optJSONArray("events"),out=new JSONArray();if(rows==null)rows=new JSONArray();for(int i=Math.max(0,rows.length()-127);i<rows.length();i++)out.put(rows.getJSONObject(i));out.put(new JSONObject().put("id",operationId).put("kind",kind).put("phase",phase).put("reason",reason).put("durationMs",Math.max(0,Math.min(86400000L,duration))).put("at",System.currentTimeMillis()));prefs(c).edit().putString("events",out.toString()).apply();}catch(Exception ignored){}}
 public static synchronized JSONObject snapshot(Context c){try{JSONArray raw=new JSONArray(prefs(c).getString("events","[]")),safe=new JSONArray();for(int i=Math.max(0,raw.length()-128);i<raw.length();i++){JSONObject row=raw.optJSONObject(i);if(row==null||!row.optString("id").matches("[a-f0-9-]{36}")||!row.optString("kind").matches("APP|CONVERSATION|PHOTO|NAVIGATION|SYNC|IMAGE|VIDEO|MEETING|IMPORT")||!row.optString("phase").matches("START|END|TIMEOUT|RESULT_UNKNOWN|RECOVERY_REQUIRED|BACKGROUND|FOREGROUND|CANCELLED|ERROR")||!row.optString("reason").matches("NONE|DEADLINE|RESTART|CONNECTION|LIFECYCLE|STATE_CHANGED"))continue;safe.put(new JSONObject().put("id",row.optString("id")).put("kind",row.optString("kind")).put("phase",row.optString("phase")).put("reason",row.optString("reason")).put("durationMs",Math.max(0,Math.min(86400000L,row.optLong("durationMs")))).put("at",Math.max(0,row.optLong("at"))));}return new JSONObject().put("schema",1).put("limit",128).put("events",safe).put("automaticReplay",false);}catch(Exception e){JSONObject out=new JSONObject();try{out.put("schema",1).put("limit",128).put("events",new JSONArray()).put("automaticReplay",false).put("metadataUnreadable",true);}catch(Exception ignored){}return out;}}
 public static synchronized void boot(Context c){boolean previous=prefs(c).getBoolean("active",false);note(c,"APP",previous?"RECOVERY_REQUIRED":"START",previous?"RESTART":"NONE",0);prefs(c).edit().putBoolean("active",true).apply();}
 public static synchronized void closed(Context c){note(c,"APP","END","LIFECYCLE",0);prefs(c).edit().putBoolean("active",false).apply();}
 private StabilityJournal(){}
}
